python3 << 'PYEOF'
import openpyxl
wb = openpyxl.load_workbook('/root/test-supply.xlsx')

# Check PWT sheet more carefully
ws = wb['PWT']
print("=== PWT columns ===")
for col in range(1, ws.max_column + 5):
    cell = ws.cell(row=1, column=col)
    print(f"Col {col} ({cell.coordinate}): {cell.value}")

# Check Production sheet row 57-75
ws2 = wb['Production']
print("\n=== Production rows 57-75 ===")
for row in range(57, 76):
    vals = []
    for col in range(1, 17):
        cell = ws2.cell(row=row, column=col)
        if cell.value is not None:
            vals.append((cell.coordinate, cell.value))
    if vals:
        print(vals)

# Check columns A and B of Production
print("\n=== Production rows 1-10, all cols ===")
for row in range(1, 30):
    vals = []
    for col in range(1, 17):
        cell = ws2.cell(row=row, column=col)
        if cell.value is not None:
            vals.append((cell.coordinate, cell.value))
    if vals:
        print(vals)

# Check if WEO_Data has more structure
ws3 = wb['WEO_Data']
print("\n=== WEO_Data all data ===")
for row in range(1, 52):
    vals = []
    for col in range(1, 5):
        cell = ws3.cell(row=row, column=col)
        if cell.value is not None:
            vals.append((cell.coordinate, cell.value))
    if vals:
        print(vals)

# Investment sheet
ws4 = wb['Investment']
print("\n=== Investment ===")
for row in range(1, 10):
    vals = []
    for col in range(1, 4):
        cell = ws4.cell(row=row, column=col)
        if cell.value is not None:
            vals.append((cell.coordinate, cell.value))
    if vals:
        print(vals)

PYEOF

